import{z as B,x as d,o as r,c as s,q as A,j as i,D as t,d as e,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"背景风险","description":"","frontmatter":{"title":"背景风险","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/background-risk.md","filePath":"econ/background-risk.md","lastUpdated":1791413859000}'),p={name:"econ/background-risk.md"};function u(m,a,D,C,c,h){const l=d("Mermaid");return r(),s("div",null,[a[2]||(a[2]=A('<h1 id="背景风险" tabindex="-1">背景风险 <a class="header-anchor" href="#背景风险" aria-label="Permalink to &quot;背景风险&quot;">​</a></h1><div class="epigraph"><p>不可保的那一份噪声，会改写人对另一份可保风险的有效厌恶——不是把 $r_A$ 估大一点，而是间接效用换了一条。</p><footer>—— 据 Gollier and Pratt, Risk Vulnerability and the Tempering Effect of Background Risk, Econometrica, 1996；Pratt, Econometrica, 1964 整理</footer></div><p><a href="/econ/prudence-kimball">上一课</a>把 \\(u&#39;&#39;&#39;\\gt 0\\) 收成谨慎，并说明预防性储蓄针对<strong>尚未保险</strong>的未来风险。本课不重写 \\(\\pi\\) 的局部公式，也不把两期欧拉再推一遍。缺口是：同一期里往往还有一份独立、不可交易的噪声 \\(\\tilde y\\)（劳动收入、健康、住房）。人对可交易风险 \\(\\tilde x\\) 的态度，不再等于无 \\(\\tilde y\\) 时的 \\(r_A\\)，而是间接效用 \\(v(w)=\\mathbb{E}u(w+\\tilde y)\\) 的厌恶。Gollier–Pratt 的风险脆弱性，说的就是这份背景如何提高有效厌恶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的噪声出现在第二期，决策是储蓄。现在两份风险同时在期末：\\(\\tilde x\\) 可在市场上加或减，\\(\\tilde y\\) 不能。若把 \\(u\\) 直接拿去对 \\(\\tilde x\\) 算 Pratt 溢价，等于假装 \\(\\tilde y\\) 不存在。缺口是定义有效效用</p> \\[v(w)=\\mathbb{E}\\bigl[u(w+\\tilde y)\\bigr], \\]<p>再读 \\(r_A^v(w)=-v&#39;&#39;(w)/v&#39;(w)\\)。一般 \\(r_A^v\\neq r_A^u\\)。背景风险改变的是<strong>对另一风险</strong>的态度，不是把 \\(\\tilde y\\) 加进方差就结束——非正态、非二次时，方差相加不是有效厌恶。</p><p>风险脆弱（risk vulnerability）：加入独立的不公平背景风险后，人对任何独立的零均值风险都变得更不愿承担。这比谨慎强，通常还要用到节制（\\(u&#39;&#39;&#39;&#39;\\) 的符号）一类的四阶条件。本课主干取 Gollier–Pratt 的定性：背景往往让人更厌恶可保风险，而不是「分散了所以更敢赌」。</p><p><span class="marginnote">数字实例：假如你面临一半概率损失 10 万元且无法投保（这就是背景风险），此时有人提议一个五五开的 ±1000 元小赌局。没有背景时你也许无所谓；有背景之后你会拒绝——因为坏状态里你更穷，那 1000 元在坏状态里的效用损失被放大了。</span></p><h3 id="独立不是可加的方差" tabindex="-1">独立不是可加的方差 <a class="header-anchor" href="#独立不是可加的方差" aria-label="Permalink to &quot;独立不是可加的方差&quot;">​</a></h3><p>\\(\\tilde x\\perp\\tilde y\\) 且 \\(\\mathbb{E}\\tilde y=0\\)，并不蕴含 \\(v\\) 比 \\(u\\) 更凹的简单比较。二次效用下方差可加，但二次已排除出主干。CARA 对独立背景有平移结构：绝对需求对财富仍无弹性，有效 \\(\\alpha\\) 仍是 \\(\\alpha\\)——指数把加性噪声提出期望。CRRA 没有这种平移，劳动收入会扭动有效 \\(\\gamma\\)。上一课边注已预告 CARA 的平移不变；本课把它当成背景风险的刀刃，不是一般结论。</p><p><span class="marginnote">Pratt 1964 比较的是两条 \\(u\\)。本课比较的是同一 \\(u\\) 在有无背景时诱导的 \\(v\\)。人际「更厌恶」与「背景使人更厌恶」是两刀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写出 \\(v\\)，再对可交易菜单用 \\(v\\) 做 EU。公平的可保风险：无背景时凹性给出全额投保；有背景时，若 \\(v\\) 仍凹（通常是），全额投保仍成立，但<strong>部分保险、资产需求</strong>的数量被 \\(r_A^v\\) 改写。检验脆弱性：看独立的零均值 \\(\\tilde x\\) 的风险溢价是否因 \\(\\tilde y\\) 上升。不必估一条新的伯努利函数。</p><p>不完全市场把 \\(\\tilde y\\) 锁在正交补里，与张成课同一几何：买不到的方向变成背景。本课先在静态财富上钉 \\(v\\)，不把一般均衡写完。</p>',15)),(r(),i(o,null,{default:t(()=>[n(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRU%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E8%B0%A8%E6%85%8E%E7%AE%A1%E5%82%A8%E8%93%84%22%5D%20--%3E%20BG%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%9D%20%E1%BB%B9%22%5D%0A%20%20BG%20--%3E%20V%5B%22v(w)%20%3D%20E%20u(w%2B%E1%BB%B9)%22%5D%0A%20%20V%20--%3E%20RA%5B%22%E6%9C%89%E6%95%88%20r_A%5Ev%22%5D%0A%20%20RA%20--%3E%20VUL%5B%22%E8%84%86%E5%BC%B1%EF%BC%9A%E5%AF%B9%E5%8F%AF%E4%BF%9D%E9%A3%8E%E9%99%A9%E6%9B%B4%E5%8E%8C%E6%81%B6%22%5D%0A%20%20CARA%5B%22CARA%20%E5%88%80%E5%88%83%EF%BC%9A%E5%B9%B3%E7%A7%BB%E4%B8%8D%E5%8F%98%22%5D%20--%3E%20EXC%5B%22%E6%9C%89%E6%95%88%20%CE%B1%20%E4%B8%8D%E5%8D%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课不把背景写成限价簿上的「未知对手」。微观结构的未知是机制，不是 \\(v\\) 的期望。也不做组合实证。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("为什么背景常常加严：\\(\\tilde y\\) 把人随机推进 \\(u\\) 更凹或 \\(r_A\\) 更大的区域（DARA 下更穷则更厌恶）。取期望之后，\\(v\\) 的局部厌恶是这些状态的加权，往往高于无噪声的 \\(r_A(w)\\)。谨慎保证对 \\(\\tilde y\\) 有预防性反应；节制一类条件再保证对"),E("strong",null,"另一份"),e("独立风险也不放松。CARA 把 \\(r_A\\) 钉死，加权改变不了 \\(\\alpha\\)，故背景不提高绝对厌恶——这是特例，用来反衬一般 DARA。")],-1)),a[6]||(a[6]=E("p",null,"与预防性储蓄的分工：谨慎回答「要不要先存」；背景回答「可保的那一份还敢不敢承担」。两份噪声可以同时存在：先因 \\(\\tilde y\\) 多存，再因 \\(r_A^v\\) 少持 \\(\\tilde x\\)。不要焊成一个弹性。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：暴风雨出海。风浪（背景风险）本身不可控，也不会直接掀翻你的决定，但它会让你对任何额外的颠簸——比如再搭小帆船出去一趟（可保风险）——都更谨慎。CARA 像装了自动配平仪：风浪多大，你对小赌局的态度都不变，这是特例。")],-1)),(r(),i(o,null,{default:t(()=>[n(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E8%83%8C%E6%99%AF%E5%99%AA%E5%A3%B0%20%E1%BB%B9%20%E5%AE%9E%E7%8E%B0%22%5D%20--%3E%20S1%5B%22%E5%9D%8F%E7%8A%B6%E6%80%81%EF%BC%9A%E8%B4%A2%E5%AF%8C%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20Y%20--%3E%20S2%5B%22%E5%A5%BD%E7%8A%B6%E6%80%81%EF%BC%9A%E8%B4%A2%E5%AF%8C%E6%9B%B4%E9%AB%98%22%5D%0A%20%20S1%20--%3E%20HI%5B%22DARA%EF%BC%9A%E8%B6%8A%E7%A9%B7%EF%BC%8C%E5%B1%80%E9%83%A8%E5%8E%8C%E6%81%B6%E8%B6%8A%E9%AB%98%22%5D%0A%20%20S2%20--%3E%20LO%5B%22%E5%A5%BD%E7%8A%B6%E6%80%81%E5%8E%8C%E6%81%B6%E8%BE%83%E4%BD%8E%22%5D%0A%20%20HI%20--%3E%20AVG%5B%22v%20%E7%9A%84%E5%8E%8C%E6%81%B6%20%3D%20%E5%90%84%E7%8A%B6%E6%80%81%E7%9A%84%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%22%5D%0A%20%20LO%20--%3E%20AVG%0A%20%20AVG%20--%3E%20UP%5B%22%E5%9D%8F%E7%8A%B6%E6%80%81%E6%9D%83%E9%87%8D%E5%A4%A7%20%E2%86%92%20%E6%9C%89%E6%95%88%E5%8E%8C%E6%81%B6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20UP%20--%3E%20DEM%5B%22%E5%AF%B9%E5%8F%AF%E4%BF%9D%E9%A3%8E%E9%99%A9%20x%20%E7%9A%84%E9%9C%80%E6%B1%82%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=A('<p><span class="marginnote">Gollier and Pratt 1996 把脆弱性与「proper」风险厌恶（Pratt–Zeckhauser）排在同一条加强凹性的梯子上。本栏主干只取：不可保风险改变有效 \\(r_A\\)，CARA 除外。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>相关背景（同一衰退里劳动与股票一起跌）比独立更糟，脆弱性的独立假设不够。本课先钉独立，相关留给宏观与资产定价。模糊没有客观 \\(\\tilde y\\) 的分布。健康、不可验证损失会把 \\(\\tilde y\\) 变成信息课的隐藏类型，不是单纯背景。</p><p>也不要把「劳动收入风险」直接叫均值方差里的第二因子。那是定价课；这里没有 \\(\\beta\\)，只有 \\(v\\)。</p><p><span class="marginnote">常见误区：「两份独立风险互相分散，总风险更可控，所以人会更敢赌。」一般情形恰好相反——背景风险让人对剩下的风险更厌恶（风险脆弱）；只有 CARA 这类特殊效用才恰好互相抵消。把方差相加当成全部，就会把方向弄反。</span></p><p>后课默认：可保风险的有效厌恶读 \\(v\\)，不读裸 \\(u\\)；CARA 下背景不改绝对厌恶。均值方差何时等于 EU，必须先声明菜单里有没有这类不可交易噪声。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不可保的独立风险把 \\(u\\) 改写成 \\(v=\\mathbb{E}u(\\cdot+\\tilde y)\\)；有效 \\(r_A\\) 一般上升。</li><li>风险脆弱：背景使人更不愿承担另一份独立零均值风险。</li><li>CARA 平移不变，有效绝对厌恶不升；CRRA/DARA 一般会升。</li><li>谨慎管跨期储蓄；背景管同期可保风险的需求。</li><li>出处：Gollier and Pratt, <em>Econometrica</em>, 1996；Pratt, <em>Econometrica</em>, 1964。</li></ul>',8))])}const g=B(p,[["render",u]]);export{_ as __pageData,g as default};
